import { useState, useEffect, useMemo } from 'react';
import { useQuery, useMutation } from '@apollo/client';
import { Bell, X, Check, ChevronUp, ChevronDown, Clock } from 'lucide-react';
import {
	GET_PENDING_SUBSCRIPTION_REQUESTS,
	APPROVE_SUBSCRIPTION_REQUEST,
	GET_USERS,
} from '@/graphql/operations/index';
import { useAppDispatch } from '@/store/hooks';
import { addToast } from '@/store/slices/uiSlice';

interface SubscriptionRequest {
	id: string;
	memberId: string;
	member: {
		id: string;
		firstName: string;
		lastName: string;
		email: string;
	};
	membershipId: string;
	membership: {
		id: string;
		name: string;
		monthlyPrice: number;
	};
	status: string;
	requestedAt: string;
	createdAt?: string | null;
	updatedAt?: string | null;
}

/** Monotonic age in seconds from `dateIso` to now (>= 0). */
function ageSeconds(dateIso: string | null | undefined): number {
	if (!dateIso) return 0;
	const t = new Date(dateIso).getTime();
	if (!Number.isFinite(t)) return 0;
	return Math.max(0, Math.floor((Date.now() - t) / 1000));
}

/** Human-readable "time since" for admin review. */
function formatRelativeSince(dateIso: string | null | undefined): string {
	const sec = ageSeconds(dateIso);
	if (sec < 60) return `${sec}s ago`;
	const min = Math.floor(sec / 60);
	if (min < 60) return `${min}m ago`;
	const hr = Math.floor(min / 60);
	if (hr < 48) return `${hr}h ago`;
	const day = Math.floor(hr / 24);
	if (day < 14) return `${day}d ago`;
	const wk = Math.floor(day / 7);
	return `${wk}w ago`;
}

/** Highlight requests waiting longer than this (seconds). */
const STALE_PENDING_SEC = 7 * 24 * 60 * 60;

export function SubscriptionRequestNotification() {
	const [isExpanded, setIsExpanded] = useState(false);
	const [isMinimized, setIsMinimized] = useState(false);
	const dispatch = useAppDispatch();

	const { data, loading, error, refetch } = useQuery<{
		getPendingSubscriptionRequests: SubscriptionRequest[];
	}>(GET_PENDING_SUBSCRIPTION_REQUESTS, {
		pollInterval: 2000,
		fetchPolicy: 'network-only',
		errorPolicy: 'all',
		skip: false,
		onError: (err) => {
			console.error('Error fetching subscription requests:', err);
		},
	});

	const [approveRequest] = useMutation(APPROVE_SUBSCRIPTION_REQUEST, {
		refetchQueries: [
			{ query: GET_USERS, variables: { role: 'member' } },
			{ query: GET_USERS, variables: { role: 'coach' } },
		],
		onCompleted: (mutationData) => {
			const membershipName =
				mutationData.approveSubscriptionRequest.membership?.name || 'the selected plan';
			dispatch(
				addToast({
					type: 'success',
					message: `Successfully subscribed member to ${membershipName}`,
				})
			);
			refetch();
		},
		onError: (mutationError) => {
			console.error('Error approving subscription request:', mutationError);
			dispatch(
				addToast({
					type: 'error',
					message: mutationError.message || 'Failed to approve subscription request',
				})
			);
		},
	});

	const pendingRequests = useMemo(() => {
		const raw = (data?.getPendingSubscriptionRequests || []).filter(
			(request) => request && request.member && request.membership && request.membership.id
		);
		const rank = (r: SubscriptionRequest) => {
			const u = r.updatedAt ? new Date(r.updatedAt).getTime() : 0;
			const q = r.requestedAt ? new Date(r.requestedAt).getTime() : 0;
			return Math.max(u, q);
		};
		return [...raw].sort((a, b) => rank(b) - rank(a));
	}, [data?.getPendingSubscriptionRequests]);

	const handleApprove = async (requestId: string) => {
		try {
			await approveRequest({
				variables: {
					input: { requestId },
				},
			});
		} catch {
			// Error handled in onError
		}
	};

	useEffect(() => {
		if (pendingRequests.length > 0 && !isMinimized) {
			setIsExpanded(true);
		}
	}, [pendingRequests.length, isMinimized]);

	if (pendingRequests.length === 0 && !isExpanded) {
		return null;
	}

	return (
		<div className="fixed bottom-6 right-6 z-50">
			{!isExpanded && (
				<button
					type="button"
					onClick={() => {
						setIsExpanded(true);
						setIsMinimized(false);
					}}
					className="relative bg-gradient-to-br from-[var(--primary-red)] to-[var(--primary-yellow)] rounded-full p-4 shadow-lg hover:shadow-xl transition-all duration-200 hover:scale-105"
				>
					<Bell className="w-6 h-6 text-white" />
					{pendingRequests.length > 0 && (
						<span className="absolute -top-1 -right-1 bg-red-500 text-white text-xs font-bold rounded-full w-6 h-6 flex items-center justify-center">
							{pendingRequests.length}
						</span>
					)}
				</button>
			)}

			{isExpanded && (
				<div className="bg-[var(--bg-darker)] border border-[rgba(255,255,255,0.1)] rounded-xl shadow-2xl w-96 max-h-[600px] flex flex-col">
					<div className="flex items-center justify-between p-4 border-b border-[rgba(255,255,255,0.1)]">
						<div className="flex items-center gap-3">
							<Bell className="w-5 h-5 text-[var(--primary-yellow)]" />
							<h3 className="text-lg font-semibold text-[var(--text-primary)]">
								Subscription Requests
							</h3>
							{pendingRequests.length > 0 && (
								<span className="bg-[var(--primary-red)] text-white text-xs font-bold rounded-full px-2 py-1">
									{pendingRequests.length}
								</span>
							)}
						</div>
						<button
							type="button"
							onClick={() => {
								setIsExpanded(false);
								setIsMinimized(true);
							}}
							className="text-[var(--text-secondary)] hover:text-[var(--text-primary)] transition-colors"
						>
							{isMinimized ? (
								<ChevronUp className="w-5 h-5" />
							) : (
								<ChevronDown className="w-5 h-5" />
							)}
						</button>
					</div>

					{!isMinimized && (
						<div className="overflow-y-auto flex-1 p-4">
							{error && (
								<div className="text-center py-4 text-red-400 text-sm">
									Error loading requests: {error.message}
								</div>
							)}
							{loading ? (
								<div className="text-center py-8 text-[var(--text-secondary)]">
									Loading requests...
								</div>
							) : pendingRequests.length === 0 ? (
								<div className="text-center py-8 text-[var(--text-secondary)]">
									<Bell className="w-12 h-12 mx-auto mb-3 opacity-50" />
									<p>No pending subscription requests</p>
								</div>
							) : (
								<div className="space-y-3">
									{pendingRequests.map((request) => {
										if (
											!request ||
											!request.member ||
											!request.membership ||
											!request.membership.id
										) {
											return null;
										}

										const ageSec = ageSeconds(request.requestedAt);
										const isStale = ageSec >= STALE_PENDING_SEC;

										return (
											<div
												key={request.id}
												className={`bg-[rgba(255,255,255,0.03)] border border-[rgba(255,255,255,0.08)] rounded-lg p-4 ${
													isStale ? 'border-amber-500/40 bg-amber-500/5' : ''
												}`}
											>
												<div className="flex items-start justify-between mb-3">
													<div className="flex-1">
														<h4 className="text-sm font-semibold text-[var(--text-primary)] mb-1">
															{request.member?.firstName || 'Unknown'}{' '}
															{request.member?.lastName || ''}
														</h4>
														<p className="text-xs text-[var(--text-secondary)] mb-2">
															{request.member?.email || 'No email'}
														</p>
														<div className="flex items-center gap-2 text-xs text-[var(--text-secondary)]">
															<span className="font-medium text-[var(--primary-yellow)]">
																{request.membership?.name || 'Unknown Plan'}
															</span>
															{request.membership?.monthlyPrice != null && (
																<>
																	<span>•</span>
																	<span>₱{request.membership.monthlyPrice.toLocaleString()}</span>
																</>
															)}
														</div>
													</div>
													<button
														type="button"
														onClick={() => {
															setIsExpanded(false);
															setIsMinimized(true);
														}}
														aria-label="Close subscription request card"
														title="Close"
														className="text-[var(--text-secondary)] hover:text-[var(--text-primary)] transition-colors ml-2"
													>
														<X className="w-4 h-4" />
													</button>
												</div>

												<div
													className={`flex flex-col gap-1 mb-3 text-xs ${
														isStale ? 'text-amber-200/90' : 'text-[var(--text-secondary)]'
													}`}
												>
													<div className="flex items-center gap-2">
														<Clock className="w-3 h-3 shrink-0" />
														<span>Request sent {formatRelativeSince(request.requestedAt)}</span>
													</div>
													{isStale && (
														<p className="pl-5 text-[11px] opacity-90">
															Pending over a week — please review soon.
														</p>
													)}
												</div>

												<div className="flex gap-2">
													<button
														type="button"
														onClick={() => handleApprove(request.id)}
														className="w-full flex items-center justify-center gap-2 bg-green-500/20 hover:bg-green-500/30 text-green-400 py-2 px-3 rounded-lg text-sm font-medium transition-colors"
													>
														<Check className="w-4 h-4" />
														Approve
													</button>
												</div>
											</div>
										);
									})}
								</div>
							)}
						</div>
					)}
				</div>
			)}
		</div>
	);
}

import { useMemo, useState } from 'react';
import { useMutation, useQuery } from '@apollo/client';
import { Bell, CheckCheck } from 'lucide-react';
import {
	GET_MY_NOTIFICATIONS,
	MARK_ALL_MY_NOTIFICATIONS_READ,
	MARK_NOTIFICATION_READ,
} from '@/graphql/operations';

type NotificationRow = {
	id: string;
	type: 'INACTIVITY' | 'MEMBERSHIP_EXPIRING';
	title: string;
	message: string;
	isRead: boolean;
	createdAt?: string | null;
};

export function SystemNotificationBell() {
	const notificationsEnabled = import.meta.env.VITE_ENABLE_SYSTEM_NOTIFICATIONS === 'true';
	const [open, setOpen] = useState(false);
	const { data, refetch } = useQuery<{ getMyNotifications: NotificationRow[] }>(
		GET_MY_NOTIFICATIONS,
		{
			variables: { limit: 20, unreadOnly: false },
			pollInterval: 30_000,
			fetchPolicy: 'network-only',
			skip: !notificationsEnabled,
		}
	);

	const [markOne] = useMutation(MARK_NOTIFICATION_READ);
	const [markAll] = useMutation(MARK_ALL_MY_NOTIFICATIONS_READ, {
		onCompleted: () => void refetch(),
	});

	const notifications = data?.getMyNotifications || [];
	const unreadCount = useMemo(
		() => notifications.filter((n) => !n.isRead).length,
		[notifications]
	);

	if (!notificationsEnabled) return null;

	const onMarkRead = async (id: string) => {
		await markOne({ variables: { id } });
		void refetch();
	};

	return (
		<div className="relative">
			<button
				type="button"
				onClick={() => setOpen((v) => !v)}
				className="relative rounded-xl bg-[rgba(255,255,255,0.05)] border border-[rgba(255,255,255,0.08)] p-2.5 text-[var(--text-primary)]"
				aria-label="System notifications"
			>
				<Bell className="w-5 h-5" />
				{unreadCount > 0 && (
					<span className="absolute -top-1 -right-1 min-w-5 h-5 px-1 rounded-full bg-[var(--primary-red)] text-white text-[10px] font-bold flex items-center justify-center">
						{unreadCount}
					</span>
				)}
			</button>

			{open && (
				<div className="absolute right-0 mt-2 w-[360px] max-h-[460px] overflow-hidden rounded-xl bg-[var(--bg-darker)] border border-[rgba(255,255,255,0.1)] shadow-[0_10px_30px_rgba(0,0,0,0.45)] z-50">
					<div className="flex items-center justify-between px-4 py-3 border-b border-[rgba(255,255,255,0.08)]">
						<h4 className="text-sm font-semibold text-[var(--text-primary)]">System Notifications</h4>
						<button
							type="button"
							onClick={() => void markAll()}
							className="text-xs text-[var(--primary-yellow)] flex items-center gap-1"
						>
							<CheckCheck className="w-3.5 h-3.5" /> Mark all read
						</button>
					</div>
					<div className="max-h-[400px] overflow-y-auto">
						{notifications.length === 0 ? (
							<p className="px-4 py-6 text-sm text-[var(--text-secondary)]">No notifications yet.</p>
						) : (
							notifications.map((n) => (
								<button
									key={n.id}
									type="button"
									onClick={() => !n.isRead && void onMarkRead(n.id)}
									className={`w-full text-left px-4 py-3 border-b border-[rgba(255,255,255,0.05)] hover:bg-[rgba(255,255,255,0.03)] ${
										n.isRead ? 'opacity-70' : ''
									}`}
								>
									<div className="flex items-center justify-between gap-2">
										<p className="text-sm font-medium text-[var(--text-primary)]">{n.title}</p>
										{!n.isRead && <span className="w-2 h-2 rounded-full bg-[var(--primary-yellow)]" />}
									</div>
									<p className="text-xs text-[var(--text-secondary)] mt-1">{n.message}</p>
									{n.createdAt && (
										<p className="text-[10px] text-[var(--text-secondary)] mt-1">
											{new Date(n.createdAt).toLocaleString('en-PH')}
										</p>
									)}
								</button>
							))
						)}
					</div>
				</div>
			)}
		</div>
	);
}

import { Outlet, Link, useLocation, useNavigate } from 'react-router';
import { useClerk } from '@clerk/clerk-react';
import { useAppSelector, useAppDispatch } from '@/store/hooks';
import { logout } from '@/store/slices/authSlice';
import { useState, useRef, useEffect } from 'react';
import {
	Home,
	Users,
	UserCog,
	CreditCard,
	BarChart3,
	Settings,
	ChevronDown,
	LogOut,
	X,
	Fingerprint,
	Clock,
	Dumbbell,
	UserRound,
} from 'lucide-react';
import { SubscriptionRequestNotification } from '../SubscriptionRequestNotification';
import { SystemNotificationBell } from '../SystemNotificationBell';

export function AdminLayout() {
	const location = useLocation();
	const dispatch = useAppDispatch();
	const { user } = useAppSelector((state) => state.auth);
	const [profileDropdownOpen, setProfileDropdownOpen] = useState(false);
	const [logoutModalOpen, setLogoutModalOpen] = useState(false);
	const [sidebarExpanded, setSidebarExpanded] = useState(false);
	const [expandedSidebarWidth, setExpandedSidebarWidth] = useState(280); // Default width
	const sidebarRef = useRef<HTMLElement>(null);
	const navigate = useNavigate();
	const { signOut } = useClerk();

	const handleLogout = async () => {
		await signOut();
		dispatch(logout());
		setLogoutModalOpen(false);
		navigate('/login');
	};

	const navItems = [
		{ path: '/dashboard', label: 'Dashboard', icon: Home },
		{ path: '/members', label: 'Member Management', icon: Users },
		{ path: '/coaches', label: 'Coach Management', icon: UserCog },
		{ path: '/memberships', label: 'Membership Management', icon: CreditCard },
		{ path: '/subscription-requests', label: 'Subscription Requests', icon: Clock },
		{ path: '/equipment', label: 'Equipment', icon: Dumbbell },
		{ path: '/attendance', label: 'Attendance Logs', icon: Fingerprint },
		{ path: '/walk-in-attendance', label: 'Walk-in Attendance', icon: UserRound },
		{ path: '/reports', label: 'Reports & Analytics', icon: BarChart3 },
	];

	// Calculate sidebar width based on longest menu item text
	useEffect(() => {
		// Create a temporary element to measure text width accurately
		const tempElement = document.createElement('span');
		tempElement.style.visibility = 'hidden';
		tempElement.style.position = 'absolute';
		tempElement.style.fontSize = '14px';
		tempElement.style.fontWeight = '500';
		tempElement.style.fontFamily = '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif';
		tempElement.style.whiteSpace = 'nowrap';
		document.body.appendChild(tempElement);

		// Find the longest label width
		let maxWidth = 0;
		navItems.forEach((item) => {
			tempElement.textContent = item.label;
			const width = tempElement.offsetWidth;
			if (width > maxWidth) {
				maxWidth = width;
			}
		});

		// Clean up
		document.body.removeChild(tempElement);

		// Calculate total width: icon (20px) + gap (12px) + text width + padding (48px total) + extra space (24px)
		const iconWidth = 20; // w-5 icon = 20px
		const gap = 12; // gap between icon and text
		const padding = 48; // 1.2rem left + 1.2rem right = 24px each = 48px total
		const extraSpace = 24; // buffer for safety and spacing

		const calculatedWidth = iconWidth + gap + maxWidth + padding + extraSpace;

		// Set width with minimum of 240px and round up to nearest 10 for clean numbers
		setExpandedSidebarWidth(Math.max(240, Math.ceil(calculatedWidth / 10) * 10));
	}, []);

	const isActive = (path: string) => location.pathname === path;

	// Sidebar hover behavior - expand on hover, collapse on leave
	useEffect(() => {
		const sidebar = sidebarRef.current;
		if (!sidebar) return;

		const handleMouseEnter = (e: MouseEvent) => {
			e.stopPropagation();
			setSidebarExpanded(true);
		};

		const handleMouseLeave = (e: MouseEvent) => {
			e.stopPropagation();
			setSidebarExpanded(false);
		};

		// Use mouseenter/mouseleave for better hover detection
		sidebar.addEventListener('mouseenter', handleMouseEnter);
		sidebar.addEventListener('mouseleave', handleMouseLeave);

		return () => {
			sidebar.removeEventListener('mouseenter', handleMouseEnter);
			sidebar.removeEventListener('mouseleave', handleMouseLeave);
		};
	}, []);

	return (
		<div
			className={`min-h-screen ${sidebarExpanded ? 'sidebar-expanded' : ''}`}
			style={
				{
					background: 'linear-gradient(135deg, var(--bg-darker) 0%, var(--bg-dark) 100%)',
					'--sidebar-width': sidebarExpanded ? `${expandedSidebarWidth}px` : '90px',
					'--sidebar-expanded-width': `${expandedSidebarWidth}px`,
				} as React.CSSProperties
			}
		>
			{/* Top Navbar */}
			<nav className="top-navbar fixed top-0 left-0 right-0 h-20 bg-[rgba(19,22,31,0.95)] backdrop-blur-md border-b border-[rgba(255,255,255,0.08)] z-50">
				<div className="flex items-center justify-between h-full px-10">
					<div className="logo flex items-center gap-3 h-10">
						<img
							src="/logo.png"
							alt="X-TRIM FIT GYM"
							className="h-full w-auto object-contain cursor-pointer"
							onClick={() => navigate('/dashboard')}
						/>
					</div>
					<div className="nav-right flex items-center gap-4">
						<SystemNotificationBell />
						<div className="relative">
							<button
								onClick={() => setProfileDropdownOpen(!profileDropdownOpen)}
								className="user-profile flex items-center gap-3 px-2 py-2.5 rounded-xl bg-[rgba(255,255,255,0.05)] border border-[rgba(255,255,255,0.08)]"
							>
								<div className="user-avatar w-9 h-9 rounded-[10px] bg-gradient-to-br from-[var(--primary-red)] to-[var(--primary-yellow)] flex items-center justify-center font-bold text-white text-sm">
									{user?.firstName?.[0] || 'A'}
									{user?.lastName?.[0] || 'D'}
								</div>
								<div className="user-info text-left hidden md:block">
									<h4 className="text-sm font-semibold text-[var(--text-primary)]">
										{user?.firstName} {user?.lastName}
									</h4>
									<p className="text-xs text-[var(--text-secondary)]">System Administrator</p>
								</div>
								<ChevronDown className="w-4 h-4 text-[var(--text-secondary)]" />
							</button>
							{profileDropdownOpen && (
								<div className="dropdown-menu absolute right-0 top-full mt-2 w-56 bg-[var(--bg-darker)] rounded-xl shadow-[0_10px_30px_rgba(0,0,0,0.5)] border border-[rgba(255,255,255,0.1)] py-2 opacity-100 visible transform-none">
									<Link
										to="/settings"
										className="dropdown-item flex items-center gap-3 px-5 py-3 text-[var(--text-secondary)] text-sm hover:bg-[rgba(255,255,255,0.05)] hover:text-[var(--primary-yellow)] hover:pl-6"
										onClick={() => setProfileDropdownOpen(false)}
									>
										<Settings className="w-5 h-5" />
										<span>Settings</span>
									</Link>
									<div className="dropdown-divider h-px bg-[rgba(255,255,255,0.08)] my-1" />
									<button
										onClick={() => {
											setLogoutModalOpen(true);
											setProfileDropdownOpen(false);
										}}
										className="dropdown-item w-full flex items-center gap-3 px-5 py-3 text-[var(--text-secondary)] text-sm hover:bg-[rgba(255,255,255,0.05)] hover:text-[#EF4444] hover:pl-6"
									>
										<LogOut className="w-5 h-5" />
										<span>Logout</span>
									</button>
								</div>
							)}
						</div>
					</div>
				</div>
			</nav>

			{/* Sidebar */}
			<aside 
				ref={sidebarRef} 
				className={`sidebar ${sidebarExpanded ? 'expanded' : ''}`}
				style={{
					width: sidebarExpanded ? `${expandedSidebarWidth}px` : '90px',
				} as React.CSSProperties}
			>
				<nav>
					<ul className="sidebar-menu">
						{navItems.map((item) => {
							const Icon = item.icon;
							return (
								<li key={item.path}>
									<Link
										to={item.path}
										className={`sidebar-menu a ${isActive(item.path) ? 'active' : ''}`}
									>
										<Icon className="w-5 h-5" />
										<span>{item.label}</span>
									</Link>
								</li>
							);
						})}
					</ul>
				</nav>
			</aside>

			{/* Main Content */}
			<main className="main-content">
				<Outlet />
			</main>

			{/* Logout Modal */}
			<div
				className={`modal-overlay ${logoutModalOpen ? 'active' : ''}`}
				onClick={() => setLogoutModalOpen(false)}
			>
				<div className="modal modal-center" onClick={(e) => e.stopPropagation()}>
					<div className="modal-body">
						<div className="modal-logout-icon">
							<LogOut className="w-10 h-10" />
						</div>
						<h3 className="modal-logout-title">Are you sure you want to logout?</h3>
						<p className="modal-logout-text">
							You'll need to log in again to access your admin account.
						</p>
						<div className="modal-logout-actions">
							<button
								type="button"
								className="btn-secondary"
								onClick={() => setLogoutModalOpen(false)}
							>
								<X className="w-4 h-4" />
								Cancel
							</button>
							<button type="button" className="btn-primary" onClick={handleLogout}>
								<LogOut className="w-4 h-4" />
								Yes, Logout
							</button>
						</div>
					</div>
				</div>
			</div>

			{/* Click outside to close dropdown */}
			{profileDropdownOpen && (
				<div className="fixed inset-0 z-30" onClick={() => setProfileDropdownOpen(false)} />
			)}

			{/* Subscription Request Notification */}
			<SubscriptionRequestNotification />
		</div>
	);
}

