function RevenueChart({
	data,
}: {
	data: Array<{
		period: string;
		revenue: number;
		count: number;
		walkInRevenue?: number;
		walkInCount?: number;
	}>;
}) {
	const subDaily = data.map((item) =>
		Math.max(0, item.revenue - (item.walkInRevenue ?? 0)),
	);
	const walkDaily = data.map((item) => item.walkInRevenue ?? 0);

	const chartData = {
		labels: data.map((item) => item.period),
		datasets: [
			{
				label: 'Membership (new sales, day)',
				data: subDaily,
				borderColor: 'rgba(249, 197, 19, 1)',
				backgroundColor: 'rgba(249, 197, 19, 0.12)',
				borderWidth: 2,
				fill: true,
				tension: 0.35,
				pointRadius: 4,
				pointHoverRadius: 6,
			},
			{
				label: 'Walk-in fees (day)',
				data: walkDaily,
				borderColor: 'rgba(16, 185, 129, 1)',
				backgroundColor: 'rgba(16, 185, 129, 0.08)',
				borderWidth: 2,
				fill: true,
				tension: 0.35,
				pointRadius: 4,
				pointHoverRadius: 6,
			},
		],
	};

	const chartOptions = {
		responsive: true,
		maintainAspectRatio: false,
		plugins: {
			legend: {
				display: true,
				position: 'top' as const,
				labels: { color: 'rgba(184, 188, 200, 0.95)', boxWidth: 12 },
			},
			tooltip: {
				backgroundColor: 'rgba(19, 22, 31, 0.95)',
				titleColor: 'rgba(255, 255, 255, 1)',
				bodyColor: 'rgba(249, 197, 19, 1)',
				borderColor: 'rgba(249, 197, 19, 0.3)',
				borderWidth: 1,
				padding: 12,
				titleFont: {
					size: 14,
					weight: 600,
					family: "'Poppins', sans-serif",
				},
				bodyFont: {
					size: 13,
					weight: 500,
					family: "'Inter', sans-serif",
				},
				callbacks: {
					afterBody: function (items: any[]) {
						const i = items[0]?.dataIndex;
						if (i == null) return '';
						const total = (subDaily[i] ?? 0) + (walkDaily[i] ?? 0);
						return `Day total: ₱${total.toLocaleString()}`;
					},
					label: function (context: any) {
						return `${context.dataset.label}: ₱${context.parsed.y.toLocaleString()}`;
					},
				},
			},
		},
		scales: {
			x: {
				grid: {
					color: 'rgba(255, 255, 255, 0.05)',
					drawBorder: false,
				},
				ticks: {
					color: 'rgba(184, 188, 200, 0.8)',
					font: {
						size: 11,
						family: "'Inter', sans-serif",
					},
				},
			},
			y: {
				grid: {
					color: 'rgba(255, 255, 255, 0.05)',
					drawBorder: false,
				},
				ticks: {
					color: 'rgba(184, 188, 200, 0.8)',
					font: {
						size: 11,
						family: "'Inter', sans-serif",
					},
					callback: function (value: any) {
						return '₱' + (value / 1000).toFixed(0) + 'k';
					},
				},
			},
		},
	};

	return (
		<div className="h-80">
			<Line data={chartData} options={chartOptions} />
		</div>
	);
}

