				const changedAt = entry?.changedAt;
				if (!changedAt) return;
				if (entry?.status !== EquipmentStatus.Undermaintenance) return;
				if (!latestIso || new Date(changedAt).getTime() > new Date(latestIso).getTime()) {
					latestIso = changedAt;
