			equipmentActionLogs.forEach((entry) => {
				if (entry.equipmentId !== item.id) return;
				const underMaintenanceAction =
					entry.actionType === 'SET_UNDER_MAINTENANCE' ||
					entry.toStatus === EquipmentStatus.Undermaintenance;
