			doc.setFont(fontFamily, 'bold');
			doc.setFontSize(9);
			doc.text(section.title.replace(/—/g, ' - '), margin, y);
			y += 4;

			autoTable(doc, {
				startY: y,
				head: [section.head],
				body: section.rows.map((row) => row.map((c) => String(c))),
				styles: {
					fontSize,
					cellPadding: 0.9,
					overflow: 'linebreak',
					font: fontFamily,
